    dirs=((1,0),(-1,0),(0,1),(0,-1))
    for r in range(n):
        for c in range(n):
            if g[r][c]==8 and (r,c) not in seen:
                comp=[]; q=deque([(r,c)]); seen.add((r,c))
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in dirs:
                        na,nb=a+da,b+db
                        if 0<=na<n and 0<=nb<n and g[na][nb]==8 and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                b=(min(rs),max(rs),min(cs),max(cs))
                key=(-(b[1]-b[0]+1)*(b[3]-b[2]+1),b[0],b[2])
                blocks.append((b,key))
    order=sorted(blocks,key=lambda x:x[1])
    out=[[0]*n for _ in range(n)]
    for idx,(b,key) in enumerate(order):
        r0,r1,c0,c1=b
        col=idx+1
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
